import json,pathlib
out=pathlib.Path('/workspace/qualification/finders/security')
f={'id':'S1','title':'Loopback Agent Mail bearer can be sent through an environment HTTP proxy','severity':'medium','evidence':'tools/agent_mail.py:25 validates only the URL hostname; tools/agent_mail.py:34 adds Authorization; tools/agent_mail.py:35 uses build_opener(NoRedirect) with its default environment ProxyHandler. docs/coordination.md promises loopback endpoint containment. Running python3 -B /workspace/qualification/finders/security/repro_proxy.py exits 0 and captures host=proxy.invalid:8080, selector=http://127.0.0.1:8765/mcp/, Authorization=Bearer SYNTHETIC-NOT-A-SECRET at HTTP dispatch, without opening a socket. See repro_proxy.json.','trigger':'An otherwise cooperative executor has http_proxy configured and no matching no_proxy exclusion for the supplied loopback hostname. No hostile actor or second PM is required.','consequence':'The proxy receives the bearer and task RPC payload over HTTP, despite the adapter accepting only a loopback endpoint. The proxy also mediates returned inbox bodies. Actual exposure depends on the executor proxy configuration; none is asserted for this environment.','reproduction':'Run the saved repro_proxy.py. It clears environment only inside a mock context, supplies synthetic http_proxy/no_proxy and token values, and patches HTTPHandler.http_open to capture the final dispatch instead of using network. Expected containment: direct 127.0.0.1 dispatch. Actual: proxy.invalid:8080 receives Authorization and private-project arguments.','unresolved_condition':'Fresh verifier has not examined this candidate; reproduction observes urllib dispatch rather than a real proxy exchange.','recommendation':'Build this loopback-only opener with urllib.request.ProxyHandler({}) alongside NoRedirect and add a socket-free regression with environment proxy variables set.'}
(out/'findings.json').write_text(json.dumps({'findings':[f]},indent=2)+'\n')
profile=json.loads((out/'preflight.json').read_text())
use={'profile':profile['profile'],'method':'review','facts':[]}
for fact in profile['commands']+profile['invariants']:
 src=next(s for s in profile['sources'] if s['id']==fact['source'])
 effect={'surface-contract':'Inspected checker, executed its exact argv from current example root; passed consistency only.', 'close-focus':'Compared Close keyboard actions and distinct summary focus assertion to contract and harness; no rendered observation.', 'back-focus':'Compared sequential Tab traversal and Enter with independent heading and returned-state assertions; browser controls skipped.', 'unanswered-scope':'Reviewed unanswered assertions and HTTP method/main-frame/popup guard placement; no live browser execution.'}[fact['id']]
 use['facts'].append({'id':fact['id'],'source':fact['source'],'current_source_sha256':src['actual_sha256'],'effect':effect})
use['surfaces_consumed']=[]
(out/'profile-use.json').write_text(json.dumps(use,indent=2)+'\n')
